pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }

    function testFuzz_property(address newOwner) public {

        address prior = c.owner();
        vm.assume(prior == address(this));

        bool ok;
        try c.setOwner(newOwner) returns (bool res) {
            ok = res;
        } catch {
            ok = false;
        }

        assertTrue(c.owner() == newOwner);
    }
}
